//===- mac_sparse.cc --------------------------------------------*- C++ -*-===//
//
// rand capture kernel for sparse MAC config mode (1, 3, 5) `2x8_8x8`
// (GENERATED by tools/gen_mac_sparse.py). Per tile and signedness flavour it builds the sparse B operand with update() from a stored-data block and a mask block,
// then runs mul, mac, msc.
// Chunk layout: 9 operand blocks of T tiles (A0 D0 M0 A1 D1 M1 A2 D2 M2).
//
//===----------------------------------------------------------------------===//

#include <stdint.h>

// Peano builds see no Chess-side define; the stream/ADF half of aie_api is not needed.
#ifndef __AIE_API_AIE_ADF_HPP__
#define __AIE_API_AIE_ADF_HPP__
#endif
#include <aie_api/aie.hpp>

#define T 8
#define OUT_WORDS_PER_TILE 384

#define STORE(r, dst) \
  do { aie::accum<acc64, 16> w(r); aie::store_v((dst), w.to_vector<int32>(0)); aie::store_v((dst) + 16, w.to_vector<int32>(32)); } while (0)

extern "C" {

void mac_sparse(uint8_t *restrict in, int32_t *restrict out) {
  uint8_t *in0 = in + 0;
  uint8_t *in1 = in + 0 + T * 64;
  uint8_t *in2 = in + 0 + T * 64 + T * 64;
  uint8_t *in3 = in + 0 + T * 64 + T * 64 + T * 16;
  uint8_t *in4 = in + 0 + T * 64 + T * 64 + T * 16 + T * 64;
  uint8_t *in5 = in + 0 + T * 64 + T * 64 + T * 16 + T * 64 + T * 64;
  uint8_t *in6 = in + 0 + T * 64 + T * 64 + T * 16 + T * 64 + T * 64 + T * 16;
  uint8_t *in7 = in + 0 + T * 64 + T * 64 + T * 16 + T * 64 + T * 64 + T * 16 + T * 64;
  uint8_t *in8 = in + 0 + T * 64 + T * 64 + T * 16 + T * 64 + T * 64 + T * 16 + T * 64 + T * 64;
  // Read the 64-bit lanes as two 32-bit halves: srs by 0 and by 32 with no saturation.
  aie::set_saturation(aie::saturation_mode::none);
  aie::set_rounding(aie::rounding_mode::floor);
  event0();
  for (int n = 0; n < T; n++) {
    int32_t *o = out + n * OUT_WORDS_PER_TILE;
    { // ss
      v32int16 a0 = *(v32int16 *)(in0 + n * 64);
      v32int16 d0 = *(v32int16 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v64int16_sparse b0;
      b0 = update(b0, d0);
      b0 = update(b0, m0);
      v32int16 a1 = *(v32int16 *)(in3 + n * 64);
      v32int16 d1 = *(v32int16 *)(in4 + n * 64);
      sparsity_t m1 = *(sparsity_t *)(in5 + n * 16);
      v64int16_sparse b1;
      b1 = update(b1, d1);
      b1 = update(b1, m1);
      v32int16 a2 = *(v32int16 *)(in6 + n * 64);
      v32int16 d2 = *(v32int16 *)(in7 + n * 64);
      sparsity_t m2 = *(sparsity_t *)(in8 + n * 16);
      v64int16_sparse b2;
      b2 = update(b2, d2);
      b2 = update(b2, m2);
      v16acc64 r0 = mul_2x8_8x8(a0, b0);
      v16acc64 r1 = mac_2x8_8x8(a1, b1, r0);
      v16acc64 r2 = msc_2x8_8x8(a2, b2, r1);
      STORE(r0, o + 0);
      STORE(r1, o + 32);
      STORE(r2, o + 64);
    }
    { // su
      v32int16 a0 = *(v32int16 *)(in0 + n * 64);
      v32uint16 d0 = *(v32uint16 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v64uint16_sparse b0;
      b0 = update(b0, d0);
      b0 = update(b0, m0);
      v32int16 a1 = *(v32int16 *)(in3 + n * 64);
      v32uint16 d1 = *(v32uint16 *)(in4 + n * 64);
      sparsity_t m1 = *(sparsity_t *)(in5 + n * 16);
      v64uint16_sparse b1;
      b1 = update(b1, d1);
      b1 = update(b1, m1);
      v32int16 a2 = *(v32int16 *)(in6 + n * 64);
      v32uint16 d2 = *(v32uint16 *)(in7 + n * 64);
      sparsity_t m2 = *(sparsity_t *)(in8 + n * 16);
      v64uint16_sparse b2;
      b2 = update(b2, d2);
      b2 = update(b2, m2);
      v16acc64 r0 = mul_2x8_8x8(a0, b0);
      v16acc64 r1 = mac_2x8_8x8(a1, b1, r0);
      v16acc64 r2 = msc_2x8_8x8(a2, b2, r1);
      STORE(r0, o + 96);
      STORE(r1, o + 128);
      STORE(r2, o + 160);
    }
    { // us
      v32uint16 a0 = *(v32uint16 *)(in0 + n * 64);
      v32int16 d0 = *(v32int16 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v64int16_sparse b0;
      b0 = update(b0, d0);
      b0 = update(b0, m0);
      v32uint16 a1 = *(v32uint16 *)(in3 + n * 64);
      v32int16 d1 = *(v32int16 *)(in4 + n * 64);
      sparsity_t m1 = *(sparsity_t *)(in5 + n * 16);
      v64int16_sparse b1;
      b1 = update(b1, d1);
      b1 = update(b1, m1);
      v32uint16 a2 = *(v32uint16 *)(in6 + n * 64);
      v32int16 d2 = *(v32int16 *)(in7 + n * 64);
      sparsity_t m2 = *(sparsity_t *)(in8 + n * 16);
      v64int16_sparse b2;
      b2 = update(b2, d2);
      b2 = update(b2, m2);
      v16acc64 r0 = mul_2x8_8x8(a0, b0);
      v16acc64 r1 = mac_2x8_8x8(a1, b1, r0);
      v16acc64 r2 = msc_2x8_8x8(a2, b2, r1);
      STORE(r0, o + 192);
      STORE(r1, o + 224);
      STORE(r2, o + 256);
    }
    { // uu
      v32uint16 a0 = *(v32uint16 *)(in0 + n * 64);
      v32uint16 d0 = *(v32uint16 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v64uint16_sparse b0;
      b0 = update(b0, d0);
      b0 = update(b0, m0);
      v32uint16 a1 = *(v32uint16 *)(in3 + n * 64);
      v32uint16 d1 = *(v32uint16 *)(in4 + n * 64);
      sparsity_t m1 = *(sparsity_t *)(in5 + n * 16);
      v64uint16_sparse b1;
      b1 = update(b1, d1);
      b1 = update(b1, m1);
      v32uint16 a2 = *(v32uint16 *)(in6 + n * 64);
      v32uint16 d2 = *(v32uint16 *)(in7 + n * 64);
      sparsity_t m2 = *(sparsity_t *)(in8 + n * 16);
      v64uint16_sparse b2;
      b2 = update(b2, d2);
      b2 = update(b2, m2);
      v16acc64 r0 = mul_2x8_8x8(a0, b0);
      v16acc64 r1 = mac_2x8_8x8(a1, b1, r0);
      v16acc64 r2 = msc_2x8_8x8(a2, b2, r1);
      STORE(r0, o + 288);
      STORE(r1, o + 320);
      STORE(r2, o + 352);
    }
  }
  event1();
}

} // extern "C"
